shader.code:
// Plasma Throat: a flight down a tunnel of living light. There are no
// surfaces: space itself is stirred by layers of turbulence, and each ray
// collects glow wherever it grazes the wound-up tunnel wall, which leaves
// luminous ribbons, membranes and veins that writhe as you pass. Every
// beat throws you forward and the whole throat convulses. In the spirit of
// Xor's volumetric turbulence shaders.

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec2 bend(float z) {
  return vec2(sin(z * 0.5), cos(z * 0.5) * 0.7 + sin(z) * 0.3);
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;
  // Mirror the view into wedges: symmetric plasma grows faces and wings.
  float seg = 3.14159265 / float(mirrors);
  float ang = atan(p.y, p.x) + j * 0.019;
  ang = abs(mod(ang, 2.0 * seg) - seg) + 0.4;
  p = length(p) * vec2(cos(ang), sin(ang));
  vec3 rd = normalize(vec3(p, mix(1.6, 0.6, fisheye)));

  // Everything along the tunnel repeats every 4 pi, so the flight can be
  // wrapped and stays precise all night.
  float fly = mod(j * 0.55, 2.0 * TAU);
  float churn = j * 0.23;
  float amp = mix(0.15, 1.0, turbulence);
  float wide = mix(0.8, 2.6, radius);
  vec2 centre = bend(fly);

  float z = 0.0;
  vec3 col = vec3(0.0);
  for (int i = 0; i < 40; i++) {
    vec3 q = rd * z;
    q.z += fly;
    q.xy += (centre - bend(q.z)) * -0.9;
    vec3 w = q;
    // Turbulence: each octave shoves the point sideways by the others.
    for (int k = 1; k < 9; k++) {
      float f = float(k);
      w += amp * sin(w.yzx * f + churn + f * 1.7) / f;
    }
    // Nested membranes around the tunnel axis, cut into ribbons.
    float len = length(w.xy);
    float wall = abs(sin((len - wide) * 2.6)) / 2.6;
    // Where a membrane crosses a sheet of the stirred space, a filament.
    float sheet = abs(sin(w.y * 2.0 + w.z)) * 0.5;
    float d = 0.006 + 0.3 * wall + 0.3 * mix(sheet, wall, veils);
    vec3 c = cos(w.z * 0.5 + len * 0.9 + w.x * 0.8 + TAU * colour + vec3(0.0, 2.1, 4.2)) + 1.0;
    col += c * c / d * exp(-z * 0.12);
    z += d;
  }

  col *= 0.00055 * mix(1.0, 0.3, veils) * mix(0.5, 2.0, glow);
  // tanh-like shoulder (no tanh in WebGL 1).
  col = 1.0 - 2.0 / (exp(2.0 * col) + 1.0);
  return clamp(col, 0.0, 1.0);
}
